tool_input.command:
cat > /etc/nginx/conf.d/benchmark-site.conf << 'EOF'
# Rate limiting zone: 10 requests per second per IP, burst of 10, 10MB zone
limit_req_zone $binary_remote_addr zone=benchmark_zone:10m rate=10r/s;

# Custom log format with timestamp, method, status, and user agent
log_format benchmark '$time_local "$request_method" $status "$http_user_agent"';

server {
    listen 8080;
    server_name localhost;

    root /var/www/html;
    index index.html;

    # Custom access log with benchmark format
    access_log /var/log/nginx/benchmark-access.log benchmark;
    error_log /var/log/nginx/benchmark-error.log;

    # Apply rate limiting: 10 requests per second per IP with burst of 10
    limit_req zone=benchmark_zone burst=10 nodelay;

    location / {
        try_files $uri $uri/ =404;
    }

    error_page 404 /404.html;
    location = /404.html {
        internal;
    }
}
EOF
cat /etc/nginx/conf.d/benchmark-site.conf

